import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the committed golden-vector corpus.
///
/// The corpus is generated by the Elixir `color_matching` service
/// (`mix parity.generate`, viamin/color_matching#112) and is the shared
/// source of truth that keeps this package's `WeightedSquaredErrorScorer`
/// and the server's `ColorMatching.WeightedSquaredError` in lockstep.
/// Each scenario is replayed through the Swift scorer with earliest-wins
/// selection (mirroring `ColorMatching.IlluminantMatching.best_match/3`)
/// and must agree with the recorded expectations **exactly**: per-candidate
/// score tables, missing-measurement exclusions, selected index/color,
/// winning error, and tie-break evidence.
///
/// Corpus location and refresh instructions: `docs/solver-parity-corpus.md`.
final class WeightedSquaredErrorParityTests: XCTestCase {
    private static let corpusURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures/ParityCorpus/corpus.json")

    private var corpus: ParityCorpus!

    override func setUpWithError() throws {
        try super.setUpWithError()
        corpus = try Self.loadCorpus()
    }

    // MARK: - Corpus metadata

    func testCorpusMetadataMatchesCurrentContract() throws {
        XCTAssertEqual(corpus.algorithmVersion, 1, """
            The upstream parity corpus moved to algorithm_version \
            \(corpus.algorithmVersion). Every expectation changed; refresh the \
            fixture and this stamp together. See docs/solver-parity-corpus.md.
            """)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.allCases.map(\.rawValue))
    }

    /// Guard mirroring the upstream corpus test: the corpus must keep
    /// exercising tie-breaking and no-selection (all-excluded) paths, or the
    /// parity guarantee silently narrows.
    func testCorpusCoversTiesAndNoSelectionScenarios() {
        let tieScenarios = corpus.scenarios.filter { $0.expected.tieBroke == true }
        let noSelectionScenarios = corpus.scenarios.filter { $0.expected.selectedIndex == nil }

        XCTAssertGreaterThanOrEqual(tieScenarios.count, 1, "corpus must contain tied scenarios")
        XCTAssertGreaterThanOrEqual(noSelectionScenarios.count, 1, "corpus must contain all-excluded scenarios")
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12)
    }

    // MARK: - Full replay

    func testEveryScenarioMatchesExpectedOutputExactly() throws {
        XCTAssertFalse(corpus.scenarios.isEmpty)
        for scenario in corpus.scenarios {
            let outcome = try replay(scenario)
            assertExactAgreement(of: outcome, with: scenario)
        }
    }

    /// The recorded winning error must equal the minimum of the numeric
    /// score table — the corpus's internal consistency, which the replay
    /// independently recomputes.
    func testRecordedErrorEqualsMinimumNumericScore() throws {
        for scenario in corpus.scenarios {
            let numeric: [Double] = scenario.expected.scores.compactMap { entry in
                guard case .number(let value) = entry.score else { return nil }
                return value
            }
            guard let minimum = numeric.min() else { continue }
            XCTAssertEqual(scenario.expected.error, minimum, "scenario \(scenario.id)")
        }
    }

    // MARK: - Replay

    /// One scored palette: the scorer results in palette order plus the
    /// earliest-wins selection derived from them.
    private struct ReplayOutcome {
        let scores: [ScorerResult]
        let selectedIndex: Int?
        let selectedHexColor: String?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]
    }

    private func replay(_ scenario: ParityScenario) throws -> ReplayOutcome {
        let weights = Self.makeWeights(scenario.weights)
        let target = Self.makeTarget(scenario.target)
        let palette = try Self.makePalette(scenario.palette)
        let scorer = WeightedSquaredErrorScorer()

        let scores = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }
        let numeric: [(index: Int, score: Double)] = scores.enumerated().compactMap { pair in
            guard case .score(let value) = pair.element else { return nil }
            return (pair.offset, value)
        }

        guard let minimum = numeric.map({ $0.score }).min() else {
            return ReplayOutcome(
                scores: scores, selectedIndex: nil, selectedHexColor: nil,
                error: nil, tieBroke: nil, tiedIndices: []
            )
        }
        let tied = numeric.filter { $0.score == minimum }.map { $0.index }
        return ReplayOutcome(
            scores: scores,
            selectedIndex: tied.first,
            selectedHexColor: tied.first.map { palette[$0].hex },
            error: minimum,
            tieBroke: tied.count > 1,
            tiedIndices: tied
        )
    }

    private func assertExactAgreement(of outcome: ReplayOutcome, with scenario: ParityScenario) {
        let expected = scenario.expected
        let id = scenario.id

        XCTAssertEqual(outcome.scores.count, expected.scores.count, "score table size [\(id)]")
        for expectedScore in expected.scores {
            guard expectedScore.index < outcome.scores.count else {
                XCTFail("score index \(expectedScore.index) out of range [\(id)]")
                continue
            }
            let actual = outcome.scores[expectedScore.index]
            switch (actual, expectedScore.score) {
            case (.excluded, .excluded):
                break
            case (.score(let value), .number(let expectedValue)):
                XCTAssertEqual(
                    value, expectedValue,
                    "score at index \(expectedScore.index) must match bit-for-bit [\(id)]"
                )
            default:
                XCTFail(
                    "score kind mismatch at index \(expectedScore.index): " +
                    "got \(actual), corpus says \(expectedScore.score) [\(id)]"
                )
            }
        }

        XCTAssertEqual(outcome.selectedIndex, expected.selectedIndex, "selected_index [\(id)]")
        XCTAssertEqual(outcome.selectedHexColor, expected.selectedHexColor, "selected_hex_color [\(id)]")
        XCTAssertEqual(outcome.error, expected.error, "winning error [\(id)]")
        XCTAssertEqual(outcome.tieBroke, expected.tieBroke, "tie_broke [\(id)]")
        XCTAssertEqual(outcome.tiedIndices, expected.tiedIndices, "tied_indices [\(id)]")
    }

    // MARK: - Corpus → domain conversion

    private static func makeWeights(_ raw: [String: Double]) -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double { raw[condition.rawValue] ?? 0 }
        // Unknown light sources in the weights map (e.g. "ultraviolet") are
        // dropped: ChannelWeights only carries the canonical conditions.
        return ChannelWeights(
            white: weight(.white), red: weight(.red), green: weight(.green),
            blue: weight(.blue), lps: weight(.lps)
        )
    }

    private static func makeTarget(_ entry: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in entry.channels {
            if let condition = LightingCondition(rawValue: key) { brightness[condition] = value }
        }
        return TargetResponseVector(brightness)
    }

    private static func makePalette(_ entries: [ParityVector]) throws -> [PaletteColor] {
        try entries
            .sorted { ($0.index ?? Int.max) < ($1.index ?? Int.max) }
            .enumerated()
            .map { pair in
                let entry = pair.element
                guard let rgb = RGBColor(hex: entry.hexColor) else {
                    XCTFail("corpus color \(entry.hexColor) is not parseable")
                    throw CocoaError(.fileReadCorruptFile)
                }
                var responses: [LightingCondition: IlluminationResponse] = [:]
                for (key, brightness) in entry.channels {
                    if let condition = LightingCondition(rawValue: key) {
                        responses[condition] = IlluminationResponse(brightness: brightness)
                    }
                }
                return PaletteColor(id: pair.offset, hex: entry.hexColor, rgb: rgb, responses: responses)
            }
    }

    // MARK: - Fixture loading

    private static func loadCorpus() throws -> ParityCorpus {
        do {
            let data = try Data(contentsOf: corpusURL)
            return try decoder.decode(ParityCorpus.self, from: data)
        } catch {
            XCTFail("""
                Could not load the parity corpus at \(corpusURL.path). \
                Refresh it per docs/solver-parity-corpus.md. Underlying error: \(error)
                """)
            throw error
        }
    }

    private static let decoder: JSONDecoder = {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return decoder
    }()
}

// MARK: - Corpus wire model (test-side mirror of `priv/parity/v1/corpus.json`)

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let description: String
    let weights: [String: Double]
    let target: ParityVector
    let palette: [ParityVector]
    let expected: ParityExpected
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]
}

private struct ParityExpected: Decodable {
    let scores: [ParityScoreEntry]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScoreEntry: Decodable {
    let index: Int
    let score: ParityScoreValue
}

/// A recorded score is either a JSON number or the string `"excluded"`.
private enum ParityScoreValue: Decodable {
    case number(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let tag = try? container.decode(String.self), tag == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "expected a numeric score or \"excluded\""
            )
        }
    }
}
